export function decodeBase64(base64: string) {
  const binaryString = atob(base64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) bytes[i] = binaryString.charCodeAt(i);
  return bytes;
}

export async function decodeAudioData(data: Uint8Array, ctx: AudioContext): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer, data.byteOffset, data.byteLength / 2);
  const buffer = ctx.createBuffer(1, dataInt16.length, 24000);
  const channelData = buffer.getChannelData(0);
  for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;
  return buffer;
}

import React, { useState, useEffect, useRef } from 'react';
import { generateAgenticBait, generateOperationalReport } from '../services/geminiService';
import { ChatMessage, ExtractedInfo, AgentResponse, AgentIntelligence } from '../types';

interface Props {
  sessionId: string;
  initialMessages: ChatMessage[];
  onMessagesUpdate: (messages: ChatMessage[]) => void;
  onIntelExtracted: (info: ExtractedInfo) => void;
  onOperationalReportGenerated?: (report: any) => void;
}

const BaitSession: React.FC<Props> = ({ sessionId, initialMessages, onMessagesUpdate, onIntelExtracted, onOperationalReportGenerated }) => {
  const [isTyping, setIsTyping] = useState(false);
  const [activeMode, setActiveMode] = useState<"normal" | "honeypot">("normal");
  const [input, setInput] = useState('');
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
    }
  }, [initialMessages, isTyping]);

  const runAgenticTurn = async (currentMessages: ChatMessage[]) => {
    setIsTyping(true);
    try {
      const history = currentMessages.map(m => ({ role: m.role, content: m.content }));
      const result: AgentResponse = await generateAgenticBait(sessionId, history);

      setActiveMode(result?.engagement?.active ? "honeypot" : "normal");

      const updatedMessages: ChatMessage[] = [...currentMessages, { 
        role: 'bot', 
        content: result.agent_reply || "...", 
        timestamp: Date.now(),
        extractedData: result.extracted_intelligence,
        verdict: result.scam_type
      }];

      onMessagesUpdate(updatedMessages);

      const intel = result.extracted_intelligence;
      const info: ExtractedInfo = {
        upiIds: (intel?.upi_ids || []).map(v => ({ value: v, confidence: 95, timestamp: Date.now() })),
        bankDetails: (intel?.bank_accounts || []).map(acc => ({ value: typeof acc === 'string' ? acc : JSON.stringify(acc), confidence: 95, timestamp: Date.now() })),
        ifscCodes: (intel?.ifsc_codes || []).map(v => ({ value: v, confidence: 95, timestamp: Date.now() })),
        phoneNumbers: (intel?.phone_numbers || []).map(v => ({ value: v, confidence: 95, timestamp: Date.now() })),
        links: (intel?.phishing_urls || []).map(v => ({ value: v, confidence: 95, timestamp: Date.now() })),
        cryptoWallets: [],
        fakeIdentities: []
      };

      onIntelExtracted(info);

      if (onOperationalReportGenerated && result?.engagement?.active) {
         const report = await generateOperationalReport(result, updatedMessages.map(m => `${m.role}: ${m.content}`).join('\n'));
         onOperationalReportGenerated(report);
      }
    } catch (e) {
      console.error("Agentic Turn Error:", e);
    } finally {
      setIsTyping(false);
    }
  };

  const handleManualScammerReply = async (reply: string) => {
    if (!reply.trim() || isTyping) return;
    const updatedMessages: ChatMessage[] = [...initialMessages, { 
      role: 'scammer', 
      content: reply, 
      timestamp: Date.now() 
    }];
    onMessagesUpdate(updatedMessages);
    setInput('');
    await runAgenticTurn(updatedMessages);
  };

  const getCaptureCount = () => {
    const lastMsg = initialMessages[initialMessages.length - 1];
    if (lastMsg?.role === 'bot' && lastMsg.extractedData) {
      const intel = lastMsg.extractedData;
      return (intel.upi_ids?.length || 0) + (intel.bank_accounts?.length || 0) + (intel.ifsc_codes?.length || 0) + (intel.phishing_urls?.length || 0);
    }
    return 0;
  };

  return (
    <div className="bg-slate-900 rounded-[3rem] border border-white/5 shadow-2xl overflow-hidden flex flex-col h-full animate-in fade-in duration-700">
      <header className={`p-8 flex items-center justify-between border-b border-white/5 transition-colors ${activeMode === 'honeypot' ? 'bg-red-600/10' : 'bg-blue-600/10'}`}>
        <div className="flex items-center space-x-5">
           <div className={`w-3 h-3 rounded-full ${activeMode === 'honeypot' ? 'bg-red-500 animate-pulse' : 'bg-blue-500'}`} />
           <div>
             <h3 className="text-sm font-black text-white uppercase tracking-widest">Sovereign Bait Agent</h3>
             <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mt-0.5">Undercover Persona Active</p>
           </div>
        </div>
        <div className="flex space-x-4">
           {getCaptureCount() > 0 && (
             <div className="bg-emerald-500/10 border border-emerald-500/20 px-3 py-1.5 rounded-xl animate-bounce">
                <span className="text-[9px] font-black text-emerald-500 uppercase tracking-widest">Intel Siphoned!</span>
             </div>
           )}
           <div className="bg-white/5 px-4 py-2 rounded-xl border border-white/10">
              <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Turns: {initialMessages.length}</span>
           </div>
        </div>
      </header>

      <div ref={scrollRef} className="flex-1 overflow-y-auto p-8 space-y-6 no-scrollbar bg-[radial-gradient(circle_at_center,_#0f172a_0%,_#020617_100%)]">
        {initialMessages.map((m, i) => (
          <div key={i} className={`flex ${m.role === 'scammer' ? 'justify-start' : 'justify-end'} animate-in slide-in-from-bottom-2`}>
            <div className={`max-w-[80%] space-y-2 ${m.role === 'scammer' ? 'items-start' : 'items-end'} flex flex-col`}>
               <span className="text-[8px] font-black text-slate-500 uppercase tracking-widest px-2">{m.role === 'scammer' ? 'Scammer (Target)' : 'Rakshak Agent (Bait)'}</span>
               <div className={`px-6 py-4 rounded-3xl text-sm leading-relaxed shadow-lg ${
                 m.role === 'scammer' 
                   ? 'bg-slate-800 text-slate-200 rounded-bl-none border border-white/5' 
                   : 'bg-blue-600 text-white rounded-br-none'
               }`}>
                 {m.content}
               </div>
               {m.extractedData && (
                 <div className="flex flex-wrap gap-1 mt-1 px-2">
                    {(m.extractedData.upi_ids || []).length > 0 && (
                      <span className="text-[8px] bg-red-500/20 text-red-400 px-2 py-0.5 rounded border border-red-500/20 font-bold uppercase tracking-widest">UPI ID Detected</span>
                    )}
                    {(m.extractedData.bank_accounts || []).length > 0 && (
                      <span className="text-[8px] bg-red-500/20 text-red-400 px-2 py-0.5 rounded border border-red-500/20 font-bold uppercase tracking-widest">Bank Details Siphoned</span>
