        id: l.id,
        type: l.scamType,
        firstMessage: l.originalMessage,
        extractedIndicators: [
            ...(l.extractedInfo?.upiIds || []).map(u => u.value),
            ...(l.extractedInfo?.phoneNumbers || []).map(p => p.value)
        ],
        tactics: l.forensicReport?.psychologicalTactics || ["Social Engineering"],
        timestamp: l.timestamp,
        patternMeta: {
          pattern: l.originalMessage.length > 60 ? l.originalMessage.substring(0, 60) + '...' : l.originalMessage,
          bank: l.sourceIntelligence?.institutionInference || "Multiple",
          method: l.channel.toUpperCase(),
          link: (l.extractedInfo?.links && l.extractedInfo.links[0]?.value) || "N/A"
        }
      }));

    const honeypotTurns = safeLogs.filter(l => (l.messages || []).length > 2);
    const honeypotSuccessRate = honeypotTurns.length 
      ? (safeLogs.filter(l => (l.extractedInfo?.upiIds || []).length > 0).length / honeypotTurns.length) * 100 
      : 0;

    return {
      totalPreventionInr: totalPrevention,
      potentialExposureInr: totalPrevention * 1.5,
      threatPosture,
      topIdentifiers,
      scamLibrary: library,
      honeypotSuccessRate,
      governanceMetrics: {
        avgPrivacyScore: 98,
        complianceRate: 100
      }
