/**
 * POST /rakshak
 * Main endpoint for processing incoming scam messages and generating agent responses.
 */
app.post('/rakshak', async (req, res) => {
  const { conversation_id, message, history = [] } = req.body;

  if (!message) {
    return res.status(400).json({ error: "Missing 'message' in request body." });
  }

  // Use process.env.API_KEY as per instructions
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    return res.status(500).json({ error: "API_KEY environment variable is not configured." });
  }

  try {
    const ai = new GoogleGenAI({ apiKey });

    // Map conversation history to Gemini parts
    const contents = history.map(item => ({
      role: item.role === 'scammer' ? 'user' : 'model',
      parts: [{ text: item.content }]
    }));

    // Add the latest incoming message
    contents.push({
      role: 'user',
      parts: [{ text: message }]
    });

    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents,
      config: {
        systemInstruction: HONEY_POT_SYSTEM_PROMPT,
        responseMimeType: "application/json",
        thinkingConfig: { thinkingBudget: 4000 }
      }
    });

    // Directly access .text property from response
    const rawText = response.text || "";
    let aiResponse;
    try {
      // Handle potential markdown formatting from model
      const jsonStr = rawText.replace(/```json\n?|```/g, '').trim();
      aiResponse = JSON.parse(jsonStr);
    } catch (parseError) {
      console.error("Failed to parse JSON from AI response:", rawText);
      throw new Error("AI returned invalid JSON.");
    }

    aiResponse.conversation_id = conversation_id || `BCR-${Date.now()}`;
    res.json(aiResponse);

  } catch (error) {
    console.error("Rakshak Internal Error:", error);
    res.status(500).json({ 
      error: "Intelligence extraction failed.", 
      details: error.message 
    });
  }
});

