                     key={i} 
                     className={`flex-1 rounded-sm transition-all duration-500 ${isActive ? 'bg-blue-500/20' : 'bg-slate-800'}`} 
                     style={{ height: isActive ? `${30 + Math.random() * 70}%` : '10%' }} 
                   />
                ))}
             </div>
             <p className="text-[9px] font-black text-slate-600 uppercase text-center tracking-widest">Supportive Voice Mode Enabled</p>
          </div>
        </div>
