    </div>
  );
};

const NavBtn = ({ active, onClick, label }: any) => (
  <button onClick={onClick} className={`px-6 py-2 rounded-full text-[11px] font-black uppercase tracking-widest transition-all ${
    active ? 'bg-navy-900 text-white shadow-md' : 'text-slate-500 hover:text-navy-900 hover:bg-slate-50'
  }`}>{label}</button>
);

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { GoogleGenAI, LiveServerMessage, Modality, Blob } from '@google/genai';
import { decodeBase64, decodeAudioData } from '../services/geminiService';
import { ScamAnalysis } from '../types';

interface Props {
  onAlert: (analysis: ScamAnalysis) => void;
}

const LiveShield: React.FC<Props> = ({ onAlert }) => {
  const [isActive, setIsActive] = useState(false);
  const [transcription, setTranscription] = useState<string[]>([]);
  const [lastSafetyAlert, setLastSafetyAlert] = useState<string | null>(null);
  const [threatLevel, setThreatLevel] = useState<'Low' | 'Medium' | 'High'>('Low');
  const [isMuted, setIsMuted] = useState(false);

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const sessionRef = useRef<any>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const frameIntervalRef = useRef<number | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());

  function encode(bytes: Uint8Array) {
    let binary = '';
    const len = bytes.byteLength;
    for (let i = 0; i < len; i++) {
      binary += String.fromCharCode(bytes[i]);
    }
    return btoa(binary);
  }

  function createBlob(data: Float32Array): Blob {
    const l = data.length;
    const int16 = new Int16Array(l);
    for (let i = 0; i < l; i++) {
      int16[i] = data[i] * 32768;
    }
    return {
      data: encode(new Uint8Array(int16.buffer)),
      mimeType: 'audio/pcm;rate=16000',
    };
  }

  const startShield = async () => {
    setIsActive(true);
    setTranscription([]);
    setLastSafetyAlert(null);
    setThreatLevel('Low');
    nextStartTimeRef.current = 0;

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true, video: true });
      if (videoRef.current) videoRef.current.srcObject = stream;

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const inputAudioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      const outputAudioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      audioContextRef.current = outputAudioContext;

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            const source = inputAudioContext.createMediaStreamSource(stream);
            const scriptProcessor = inputAudioContext.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              if (isMuted) return;
              const inputData = e.inputBuffer.getChannelData(0);
              const pcmBlob = createBlob(inputData);
              sessionPromise.then(s => s.sendRealtimeInput({ media: pcmBlob }));
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputAudioContext.destination);

            const ctx = canvasRef.current?.getContext('2d');
            frameIntervalRef.current = window.setInterval(() => {
              if (videoRef.current && canvasRef.current && ctx) {
                canvasRef.current.width = 160; 
                canvasRef.current.height = 120;
                ctx.drawImage(videoRef.current, 0, 0, 160, 120);
                const base64 = canvasRef.current.toDataURL('image/jpeg', 0.3).split(',')[1];
                sessionPromise.then(s => s.sendRealtimeInput({ media: { data: base64, mimeType: 'image/jpeg' } }));
              }
            }, 3000); 
          },
          onmessage: async (msg: LiveServerMessage) => {
            if (msg.serverContent?.inputTranscription) {
              const text = msg.serverContent.inputTranscription.text;
              setTranscription(prev => [...prev.slice(-4), `Adversary: ${text}`]);
              checkScamTriggers(text);
            }
            if (msg.serverContent?.outputTranscription) {
              const text = msg.serverContent.outputTranscription.text;
              setTranscription(prev => [...prev.slice(-4), `AI Defense: ${text}`]);
            }

            const base64EncodedAudioString = msg.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
            if (base64EncodedAudioString && audioContextRef.current) {
              const ctx = audioContextRef.current;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
              const audioBuffer = await decodeAudioData(decodeBase64(base64EncodedAudioString), ctx);
              const source = ctx.createBufferSource();
              source.buffer = audioBuffer;
              source.connect(ctx.destination);
              source.addEventListener('ended', () => {
                sourcesRef.current.delete(source);
              });

              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += audioBuffer.duration;
              sourcesRef.current.add(source);
            }

            if (msg.serverContent?.interrupted) {
              for (const source of sourcesRef.current.values()) {
                try { source.stop(); } catch(e) {}
                sourcesRef.current.delete(source);
              }
              nextStartTimeRef.current = 0;
            }
          },
          onerror: (e) => console.error("LiveShield Error", e),
          onclose: (e) => stopShield(),
        },
        config: {
          responseModalities: [Modality.AUDIO],
          inputAudioTranscription: {},
          outputAudioTranscription: {},
          systemInstruction: `You are the Bharat Cyber Rakshak Call Shield. 
          You are protecting an Indian citizen from high-pressure voice calls.

          VOICE DEFENSE PROTOCOL:
          1. Monitor for "Digital Arrest" threats, "CBI/Police" impersonation, and "Aadhaar linked to crime" scripts.
          2. If a scam is detected, speak immediately in a calm, authoritative voice to the user.
          3. Say: "This is Bharat Cyber Rakshak. Please listen to me: You are being scammed. Hang up now. No legitimate officer will ask for money over a video or audio call."
          4. If the scammer is using high-pressure tactics, increase your verbal reassurance to the user.
          5. Transcribe accurately for forensic reporting.`
        }
      });

      sessionRef.current = await sessionPromise;
    } catch (err) {
      console.error("Shield activation failed", err);
      setIsActive(false);
    }
  };

  const checkScamTriggers = (text: string) => {
    const triggers = ['police', 'customs', 'arrest', 'drug parcel', 'illegal activities', 'money laundering', 'cbi', 'frozen account', 'urgent transfer'];
    const lowerText = text.toLowerCase();
    const found = triggers.filter(t => lowerText.includes(t));

    if (found.length > 0) {
      setThreatLevel('High');
      const safetyMsg = `🚨 CRITICAL CALL ALERT: IMPERSONATION DETECTED. The caller is using "Digital Arrest" tactics. Hang up immediately and report to 1930.`;
      setLastSafetyAlert(safetyMsg);

      onAlert({
        isScam: true,
        confidence: 0.98,
        scamType: "Digital Arrest Voice Call",
        channel: 'call',
        threatLevel: 'High',
        summary: `Real-time intercept: Scammer mentioned ${found.join(', ')}. High-pressure delivery.`,
        safetyAlert: safetyMsg,
        extractedInfo: { upiIds: [], bankDetails: [], ifscCodes: [], phoneNumbers: [], links: [], cryptoWallets: [], fakeIdentities: [] },
        killChainStage: 'Exploitation',
        fingerprint: { primaryHandle: 'VOICE_FEED', primaryPhone: '', primaryLink: '', category: 'Voice' },
        recommendedActions: ["End call immediately.", "Call 1930.", "Do not reveal Aadhaar details."]
      });
    }
  };

  const stopShield = () => {
    if (sessionRef.current) sessionRef.current.close();
    if (frameIntervalRef.current) clearInterval(frameIntervalRef.current);
    if (videoRef.current?.srcObject) {
      (videoRef.current.srcObject as MediaStream).getTracks().forEach(t => t.stop());
    }
    setIsActive(false);
    setThreatLevel('Low');
  };

  return (
    <div className="bg-[#020617] rounded-[3rem] shadow-2xl border border-white/5 overflow-hidden relative">
      <div className={`px-10 py-10 flex items-center justify-between border-b border-white/5 ${isActive ? 'bg-blue-600/10' : 'bg-slate-900/50'}`}>
        <div className="flex items-center space-x-6">
          <div className={`p-5 rounded-3xl transition-all ${isActive ? 'bg-blue-600 shadow-[0_0_30px_#3b82f6]' : 'bg-white/5'}`}>
            <svg className={`w-10 h-10 ${isActive ? 'text-white' : 'text-slate-700'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M3 5a2 2 0 012-2h3.28a1 1 0 01.948.684l1.498 4.493a1 1 0 01-.502 1.21l-2.257 1.13a11.042 11.042 0 005.516 5.516l1.13-2.257a1 1 0 011.21-.502l4.493 1.498a1 1 0 01.684.949V19a2 2 0 01-2 2h-1C9.716 21 3 14.284 3 6V5z" /></svg>
          </div>
          <div>
            <h3 className="text-3xl font-black text-white tracking-tight uppercase">Call Protection Shield</h3>
            <p className="text-[10px] font-black text-slate-500 uppercase tracking-[0.4em] mt-1">{isActive ? 'AI SENTINEL ACTIVE ON LIVE FEED' : 'VOICE-ONLY DEFENSE ENGINE STANDBY'}</p>
          </div>
        </div>
        <div className="flex items-center space-x-4">
           {isActive && (
             <div className="flex items-center space-x-3 bg-red-600/10 border border-red-500/20 px-6 py-2.5 rounded-2xl">
                <div className="w-2.5 h-2.5 bg-red-600 rounded-full animate-ping"></div>
                <span className="text-[10px] font-black text-red-500 uppercase tracking-widest">Encrypted Monitoring</span>
             </div>
           )}
           <button
             onClick={isActive ? stopShield : startShield}
             className={`px-10 py-4 rounded-2xl font-black text-xs uppercase tracking-[0.3em] transition-all active:scale-[0.98] shadow-2xl ${
               isActive 
               ? 'bg-red-600 text-white hover:bg-red-500 shadow-red-900/40' 
               : 'bg-blue-600 text-white hover:bg-blue-500 shadow-blue-900/40'
             }`}
           >
             {isActive ? 'Disconnect' : 'Secure Call'}
           </button>
        </div>
      </div>

      <div className="p-10 grid grid-cols-1 lg:grid-cols-2 gap-10">
        <div className="space-y-8">
          <div className="aspect-square bg-slate-900 rounded-[3rem] overflow-hidden relative shadow-inner border border-white/5 flex flex-col items-center justify-center">
             {!isActive ? (
               <div className="text-center space-y-6 opacity-20 group">
                 <div className="w-32 h-32 mx-auto rounded-full border-2 border-dashed border-slate-700 flex items-center justify-center">
                   <svg className="w-16 h-16 text-slate-700" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>
                 </div>
                 <p className="text-[10px] font-black uppercase tracking-[0.5em]">Awaiting Live Call Feed</p>
               </div>
             ) : (
               <div className="w-full h-full p-12 flex flex-col justify-between">
                 <div className="flex justify-between items-start">
                    <div className="space-y-1">
                       <span className="text-[9px] font-black text-blue-500 uppercase tracking-widest">Security Status</span>
                       <div className="text-xl font-black text-white uppercase tracking-tighter">Verified Link</div>
                    </div>
                    <div className="bg-blue-600/10 px-4 py-2 rounded-2xl border border-blue-500/20 text-[10px] font-black text-blue-400">00:{Math.floor(Date.now()/1000 % 60).toString().padStart(2, '0')} INTERCEPT</div>
                 </div>

                 <div className="flex items-center justify-center space-x-2 h-32">
                    {[...Array(30)].map((_, i) => (
                      <div 
                        key={i} 
                        className="w-1.5 bg-blue-600 rounded-full transition-all duration-75" 
                        style={{ height: `${20 + Math.random() * 80}%`, opacity: 0.3 + (i/30)*0.7 }} 
                      />
                    ))}
                 </div>

                 <div className="space-y-3">
                    {transcription.map((line, i) => (
                      <div key={i} className={`text-[11px] font-bold px-5 py-3 rounded-2xl w-fit animate-in slide-in-from-left-2 backdrop-blur-2xl border border-white/5 ${
                        line.startsWith('AI') ? 'bg-blue-600 text-white' : 'bg-slate-800 text-slate-400'
                      }`}>
                        {line}
                      </div>
                    ))}
                 </div>

                 <div className="flex justify-center space-x-6">
                    <button onClick={() => setIsMuted(!isMuted)} className={`w-14 h-14 rounded-full flex items-center justify-center transition-all ${isMuted ? 'bg-red-600 text-white' : 'bg-white/5 text-slate-400 border border-white/10 hover:bg-white/10'}`}>
                      {isMuted ? '🔇' : '🎙️'}
                    </button>
                    <button onClick={stopShield} className="w-14 h-14 bg-red-600 rounded-full flex items-center justify-center text-white shadow-xl shadow-red-900/40">
                      📞
                    </button>
                 </div>
               </div>
             )}
          </div>
        </div>

        <div className="flex flex-col space-y-10">
          <div className={`flex-1 p-12 rounded-[3rem] border transition-all duration-700 flex flex-col items-center justify-center text-center space-y-8 shadow-2xl relative overflow-hidden ${
            threatLevel === 'High' ? 'bg-red-600/10 border-red-500/30' : 'bg-black/40 border-white/5'
          }`}>
            {threatLevel === 'High' ? (
              <>
                <div className="w-28 h-28 bg-red-600 rounded-[2.5rem] flex items-center justify-center shadow-2xl shadow-red-500/40 animate-bounce relative z-10">
                  <svg className="w-14 h-14 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
                </div>
                <div className="relative z-10 space-y-4">
                  <h4 className="text-4xl font-black text-red-500 uppercase tracking-tighter">Fraud Strategy Identified</h4>
                  <p className="text-lg font-bold text-white leading-tight px-6 max-w-sm mx-auto">{lastSafetyAlert}</p>
                </div>
                <div className="pt-6 flex flex-col space-y-4 w-full max-w-xs relative z-10">
                  <button onClick={stopShield} className="w-full py-4 bg-red-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-red-500 shadow-xl transition-all active:scale-95">Hang Up Now</button>
                  <button className="w-full py-4 bg-white/5 text-slate-500 rounded-2xl text-[10px] font-black uppercase tracking-widest border border-white/5 transition-all">Report to 1930</button>
                </div>
              </>
            ) : (
              <>
                <div className={`w-24 h-24 rounded-[2rem] flex items-center justify-center transition-all relative ${isActive ? 'bg-blue-600 shadow-[0_0_40px_rgba(59,130,246,0.3)]' : 'bg-white/5'}`}>
                  {isActive && <div className="absolute inset-0 bg-blue-500 rounded-[2rem] animate-ping opacity-20" />}
                  <svg className={`w-12 h-12 ${isActive ? 'text-white' : 'text-slate-700'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z" /></svg>
                </div>
                <div className="space-y-4">
                  <h4 className="text-2xl font-black text-white uppercase tracking-tight">{isActive ? 'Call Protection Ready' : 'System Standby'}</h4>
                  <p className="text-sm font-medium text-slate-500 max-w-sm mx-auto leading-relaxed">
                    Once you start the Call Shield, Bharat Cyber Rakshak will monitor the audio and use its voice to warn you if a scam is detected.
                  </p>
                </div>
              </>
            )}
          </div>

          <div className="bg-white/5 border border-white/5 rounded-[2.5rem] p-10 flex flex-col justify-between h-48">
             <div className="flex justify-between items-center text-[10px] font-black text-blue-500 uppercase tracking-[0.4em]">
                <span>Voice Forensic Confidence</span>
                <span>Active 16kHz Stream</span>
             </div>
             <div className="flex items-end space-x-1 flex-1 py-6">
                {[...Array(15)].map((_, i) => (
                   <div 
                     key={i} 
                     className={`flex-1 rounded-sm transition-all duration-500 ${isActive ? 'bg-blue-600/40' : 'bg-slate-800'}`} 
                     style={{ height: isActive ? `${20 + Math.random() * 80}%` : '10%' }} 
                   />
                ))}
             </div>
             <p className="text-[9px] font-black text-slate-600 uppercase text-center tracking-widest">Real-time Acoustic Analysis Active</p>
          </div>
        </div>
      </div>

