        extractedIndicators: [
          ...(l.extractedInfo?.upiIds || []).map(u => u.value),
          ...(l.extractedInfo?.phoneNumbers || []).map(p => p.value),
          ...(l.extractedInfo?.links || []).map(link => link.value)
        ],
        tactics: l.forensicReport?.psychologicalTactics || ["Social Engineering"],
        timestamp: l.timestamp,
        patternMeta: {
          pattern: l.originalMessage.length > 50 ? l.originalMessage.substring(0, 50) + '...' : l.originalMessage,
          bank: l.sourceIntelligence?.institutionInference || "Generic",
          method: l.channel.toUpperCase(),
          link: (l.extractedInfo?.links && l.extractedInfo.links[0]?.value) || "N/A"
        }
      }));
  }, [logs]);

  const currentSessionIdRef = useRef<string | null>(null);

  useEffect(() => {
    const checkKey = async () => {
      if ((window as any).aistudio?.hasSelectedApiKey) {
        const has = await (window as any).aistudio.hasSelectedApiKey();
        setHasApiKey(has);
      }
    };
    checkKey();
  }, []);

  const generateCaseId = () => `BCR-${new Date().getFullYear()}-${Math.floor(1000 + Math.random() * 9000)}`;

  const runSimulation = (count: number = 500) => {
    setIsSimulating(true);
    setSimProgress(0);
    setView('intelligence');
    let currentCount = 0;
    const batchSize = 25;
    const interval = setInterval(() => {
      const nextBatch = [];
      for(let i = 0; i < batchSize && currentCount < count; i++) {
        const id = `SIM-${Date.now()}-${currentCount}`;
        const simulated = generateSimulatedCase(id);
        nextBatch.push(simulated);
        currentCount++;
      }
      setLogs(prev => [...nextBatch, ...prev]);
      setSimProgress(Math.round((currentCount / count) * 100));
      if (currentCount >= count) {
        clearInterval(interval);
        setIsSimulating(false);
        setShowSimReport(true);
      }
    }, 500);
  };

  const handleManualAnalyze = async (message: string) => {
    setApiError(null);
    try {
      const analysisResult = await analyzeMessage(message, scamLibrary);
      handleAnalysisComplete(message, analysisResult, true);
    } catch (e: any) {
      setApiError(e.message);
      setTimeout(() => setApiError(null), 5000);
    }
  };

  const handleAnalysisComplete = (message: string, analysis: ScamAnalysis, isNewSession: boolean = false) => {
    if (isNewSession || !currentSessionIdRef.current) currentSessionIdRef.current = generateCaseId();
    const sessionId = currentSessionIdRef.current;

    const linkedCases = (logs || []).filter(prevLog => {
      if (prevLog.id === sessionId) return false;
      const upiMatch = (analysis.extractedInfo?.upiIds || []).some(u => 
        (prevLog.extractedInfo?.upiIds || []).some(pu => pu.value.toLowerCase() === u.value.toLowerCase())
      );
      return upiMatch;
    }).map(l => l.id);

    const existingLog = (logs || []).find(l => l.id === sessionId);
    const newLog: IntelligenceLog = {
      ...analysis,
      id: sessionId,
      originalMessage: message,
      timestamp: Date.now(),
      status: 'Open',
      linkedCaseIds: linkedCases,
      operationalRequests: [],
      governance: {
        privacyScore: 98,
        evidenceIntegrityHash: `SHA256:${Math.random().toString(16).substr(2, 40).toUpperCase()}`,
        ethicsChecklist: { confirmed: true },
        legalStanding: 'Active Investigation',
        auditLog: []
      },
      messages: analysis.isScam ? (existingLog ? existingLog.messages : [{ role: 'scammer', content: message, timestamp: Date.now() }]) : []
    };

    setLogs(prev => {
      const existingIdx = prev.findIndex(l => l.id === sessionId);
      if (existingIdx >= 0) return prev.map(l => l.id === sessionId ? newLog : l);
      return [newLog, ...prev];
    });

    setLatestAnalysis({ message, analysis: newLog, sessionId });

    if (analysis.threatLevel === 'High' || analysis.threatLevel === 'Critical') {
      setActiveAlert({
        level: analysis.threatLevel,
        message: analysis.safetyAlert,
        details: "Collecting evidence from the scammer automatically.",
        isEngaging: true
      });
    }
  };

  const updateOperationalReport = (sessionId: string, report: OperationalReport) => {
    setLogs(prev => prev.map(l => l.id === sessionId ? { ...l, operationalReport: report } : l));
    if (latestAnalysis?.sessionId === sessionId) {
      setLatestAnalysis(prev => prev ? { ...prev, analysis: { ...prev.analysis, operationalReport: report } } : null);
    }
  };

  return (
    <div className="min-h-screen flex flex-col selection:bg-navy-500/10">
      {/* API Quota Alert */}
      {apiError && (
        <div className="fixed top-4 left-1/2 -translate-x-1/2 z-[1000] w-full max-w-md px-6 animate-in slide-in-from-top-4">
          <div className="bg-red-600 text-white p-4 rounded-2xl shadow-2xl flex items-center justify-between border border-white/20">
            <div className="flex items-center space-x-3">
              <span className="text-xl">⚠️</span>
              <div>
                <p className="text-xs font-black uppercase">Quota Warning</p>
                <p className="text-[10px] font-bold opacity-90">{apiError}</p>
              </div>
            </div>
            <button onClick={() => setApiError(null)} className="text-white/50 hover:text-white">✕</button>
          </div>
        </div>
      )}

      {isSimulating && (
        <div className="fixed top-0 left-0 w-full h-1 bg-slate-200 z-[100]">
          <div className="h-full bg-blue-600 transition-all duration-300" style={{ width: `${simProgress}%` }} />
        </div>
      )}

      {showSimReport && (
        <div className="fixed inset-0 z-[200] bg-black/60 backdrop-blur-md flex items-center justify-center p-6">
           <div className="max-w-2xl w-full bg-white border border-slate-200 rounded-[2.5rem] p-10 space-y-6 shadow-2xl animate-in zoom-in-95">
              <div className="flex justify-between items-start">
                 <h2 className="text-2xl font-black text-navy-900 uppercase">Stress Test Result</h2>
                 <button onClick={() => setShowSimReport(false)} className="text-slate-400">✕</button>
              </div>
              <p className="text-slate-600 font-medium">The Sovereign AI Shield has processed the requests. System integrity is at 100%.</p>
              <button onClick={() => setShowSimReport(false)} className="w-full py-4 bg-navy-600 text-white rounded-2xl font-bold">Close Report</button>
           </div>
        </div>
      )}

      {showTutorial && (
        <OnboardingTour activeView={view} onViewChange={(v) => setView(v)} onComplete={() => setShowTutorial(false)} />
      )}

      {showTutor && (
        <RakshakTutor onClose={() => setShowTutor(false)} />
      )}

      <button 
        onClick={() => setShowTutor(!showTutor)}
        className="fixed bottom-8 left-8 z-[150] w-14 h-14 bg-navy-600 rounded-2xl flex items-center justify-center text-white shadow-2xl hover:bg-navy-500 transition-all active:scale-95 group"
      >
        <span className="text-2xl">🧑‍🏫</span>
      </button>

      <header className="bg-white px-6 py-4 flex items-center justify-between sticky top-0 z-[60] border-b border-slate-100 gap-4">
        <div className="flex items-center space-x-4">
          <div className="bg-navy-600 p-2 rounded-xl shadow-lg">
            <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z" /></svg>
          </div>
          <button onClick={() => {setView('home'); setLatestAnalysis(null);}} className="text-left">
            <h1 className="text-xl font-extrabold tracking-tight text-navy-900">BHARAT CYBER <span className="text-blue-600">RAKSHAK</span></h1>
          </button>
        </div>

        <nav className="hidden lg:flex items-center space-x-1">
           <NavBtn active={view === 'home'} onClick={() => setView('home')} label="Check" />
           <NavBtn active={view === 'multimedia'} onClick={() => setView('multimedia')} label="Call Defense" />
           <NavBtn active={view === 'history'} onClick={() => setView('history')} label="History" />
           <NavBtn active={view === 'intelligence'} onClick={() => setView('intelligence')} label="Stats" />
           <NavBtn active={view === 'warroom'} onClick={() => setView('warroom')} label="War Room" />
           <NavBtn active={view === 'api'} onClick={() => setView('api')} label="API Hub" />
        </nav>

        <div className="flex items-center space-x-4">
           {/* Scope & Intensity Toggles */}
           <div className="flex items-center bg-slate-100 p-1 rounded-full border border-slate-200">
              <button 
                onClick={toggleScope}
                className={`px-4 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest transition-all ${scope === 'National' ? 'bg-white text-navy-900 shadow-sm' : 'text-slate-500'}`}
              >
                National
              </button>
              <button 
                onClick={toggleScope}
                className={`px-4 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest transition-all ${scope === 'Global' ? 'bg-blue-600 text-white shadow-sm' : 'text-slate-500'}`}
              >
                Global
              </button>
           </div>

           <div className="flex items-center bg-slate-100 p-1 rounded-full border border-slate-200">
              <button 
                onClick={toggleIntensity}
                className={`px-4 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest transition-all ${intensity === 'standard' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}
              >
                Std
              </button>
              <button 
                onClick={toggleIntensity}
                className={`px-4 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest transition-all ${intensity === 'deep' ? 'bg-navy-900 text-white shadow-sm' : 'text-slate-500'}`}
              >
                Deep
              </button>
           </div>

           {/* API Health Monitor */}
           <div className={`flex items-center space-x-2 px-3 py-1.5 rounded-full border transition-all ${isThrottled ? 'bg-amber-50 border-amber-200' : 'bg-green-50 border-green-200'}`}>
              <div className={`w-1.5 h-1.5 rounded-full ${isThrottled ? 'bg-amber-500 animate-pulse' : 'bg-green-500'}`} />
              <span className={`text-[9px] font-black uppercase tracking-widest ${isThrottled ? 'text-amber-700' : 'text-green-700'}`}>
                {isThrottled ? 'Throttled' : 'Nominal'}
              </span>
           </div>
        </div>
      </header>

      <SafetyBanner alert={activeAlert} onDismiss={() => setActiveAlert(null)} />

      <main className="flex-1">
        {view === 'home' ? (
          <div className="animate-in fade-in duration-700">
             <div className="hero-pattern py-20 px-6 text-center text-white mb-12">
                <div className="max-w-3xl mx-auto space-y-6">
                   <h2 className="text-5xl font-black tracking-tight leading-tight">Universal AI Cyber Safety Guardian</h2>
                   <p className="text-lg text-blue-100 font-medium">Protecting {scope === 'Global' ? 'the world' : 'India'} from fraud with sovereign {scope === 'Global' ? 'multi-modal' : ''} intelligence.</p>
                   <div className="pt-8">
                      <div className="max-w-2xl mx-auto bg-white rounded-[2.5rem] p-2 shadow-2xl flex flex-col md:flex-row gap-2">
                        <input 
                          className="flex-1 px-8 py-4 text-slate-900 placeholder:text-slate-400 text-lg outline-none rounded-full"
                          placeholder={`Paste a ${scope.toLowerCase()} suspicious message here...`}
                          onKeyDown={(e) => {
                            if (e.key === 'Enter') handleManualAnalyze((e.target as HTMLInputElement).value);
                          }}
                        />
                        <button onClick={() => {
                            const input = document.querySelector('input');
                            if (input) handleManualAnalyze(input.value);
                          }}
                          className="px-10 py-4 bg-blue-600 hover:bg-blue-500 text-white rounded-[2rem] font-bold text-lg transition-all shadow-lg active:scale-95"
                        >Check Safety</button>
                      </div>
                   </div>
                </div>
             </div>

             {latestAnalysis && (
               <div id="results-anchor" className="container mx-auto px-6 max-w-5xl py-12 space-y-12 animate-in slide-in-from-bottom-10">
                 <ResultPanel analysis={latestAnalysis.analysis} onClose={() => setLatestAnalysis(null)} />
                 {latestAnalysis.analysis.isScam && (
                    <div className="h-[800px]">
                      <BaitSession 
                        sessionId={latestAnalysis.sessionId}
                        initialMessages={(logs || []).find(l => l.id === latestAnalysis.sessionId)?.messages || []}
                        onMessagesUpdate={(msgs) => setLogs(prev => prev.map(l => l.id === latestAnalysis.sessionId ? { ...l, messages: msgs } : l))}
                        onIntelExtracted={(info) => setLogs(prev => prev.map(l => l.id === latestAnalysis.sessionId ? { ...l, extractedInfo: info } : l))}
                        onOperationalReportGenerated={(report) => updateOperationalReport(latestAnalysis.sessionId, report)}
                      />
                    </div>
                 )}
               </div>
             )}
          </div>
        ) : view === 'intelligence' ? (
          <div className="container mx-auto px-6 py-12 max-w-7xl"><IntelligenceDashboard logs={logs || []} /></div>
        ) : view === 'warroom' ? (
          <div className="container mx-auto px-6 py-12 max-w-7xl"><WarRoom logs={logs || []} onRunSimulation={runSimulation} hasKey={hasApiKey} /></div>
        ) : view === 'history' ? (
          <div className="container mx-auto px-6 py-12 max-w-7xl"><CaseHistory logs={logs || []} onUpdateStatus={() => {}} onSendRequest={() => {}} /></div>
        ) : view === 'api' ? (
          <div className="container mx-auto px-6 py-12 max-w-7xl space-y-12">
            <ApiDeveloperHub />
            <div className="h-[2px] bg-slate-100 w-full" />
            <div className="space-y-6">
              <h3 className="text-2xl font-black text-navy-900 uppercase">Interactive API Explorer</h3>
              <ApiExplorer />
            </div>
          </div>
        ) : (
          <div className="container mx-auto px-6 py-12 max-w-7xl space-y-16 animate-in fade-in">
             <LiveShield onAlert={(analysis) => handleAnalysisComplete("LIVE_SHIELD", analysis, true)} />
             <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
                <VideoScanner />
             </div>
          </div>
        )}
      </main>
    </div>
  );
};

const NavBtn = ({ active, onClick, label }: any) => (
  <button onClick={onClick} className={`px-6 py-2 rounded-full text-[11px] font-black uppercase tracking-widest transition-all ${
    active ? 'bg-navy-900 text-white shadow-md' : 'text-slate-500 hover:text-navy-900 hover:bg-slate-50'
  }`}>{label}</button>
);

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { IntelligenceLog, AnalyticsSummary, ThreatPosture, ScamSignature } from '../types';
import { apiStatus } from '../services/geminiService';

interface Props {
  logs: IntelligenceLog[];
}

const KPIBox = ({ title, value, sub, color }: any) => (
  <div className="bg-white p-8 rounded-[2rem] border border-slate-200 shadow-xl flex flex-col justify-center transition-all hover:shadow-2xl">
    <div className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">{title}</div>
    <div className={`text-4xl font-black tracking-tighter ${color}`}>{value}</div>
    <div className="mt-2 text-[9px] font-bold text-slate-500 uppercase tracking-widest">{sub}</div>
  </div>
);

const TabNav = ({ active, onClick, label }: any) => (
  <button
    onClick={onClick}
    className={`px-6 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${
      active ? 'bg-white text-blue-600 shadow-md' : 'text-slate-500 hover:text-slate-900'
    }`}
  >
    {label}
  </button>
);

const IntelligenceDashboard: React.FC<Props> = ({ logs }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'library' | 'global'>('overview');
  const [globalStream, setGlobalStream] = useState<any[]>([]);

  const currentLogs = Array.isArray(logs) ? logs : [];
  const scope = apiStatus.defenseScope;

  useEffect(() => {
    const events = [
      "Agent 'Kore' intercepted UPI handle in Jamtara cluster.",
      "Autonomous bypass of remote-access request detected.",
      "New Phishing pattern identified in urban Delhi-NCR zone.",
      "Scammer psychological suspicion increased to 45% (Mumbai).",
      "Synthetic Identity 'Officer Sharma' successfully deployed.",
      "Cross-border laundering vector identified: Hong Kong Node -> Mumbai.",
      "SE-Asia 'Pig Butchering' cluster sync complete. 12 IoCs added.",
      "Interpol shared forensic hash for global tech support campaign.",
      "Institutional block request sent to SBI for account: 9182***"
    ];
    const interval = setInterval(() => {
      setGlobalStream(prev => [events[Math.floor(Math.random() * events.length)], ...prev].slice(0, 5));
    }, 4000);
    return () => clearInterval(interval);
  }, []);

  const analytics = useMemo((): AnalyticsSummary => {
    const totalPrevention = currentLogs.reduce((sum, log) => sum + (log.estimatedImpact || 0), 0);

    const recentLogs = currentLogs.filter(l => l.timestamp > Date.now() - 3600000);
    let threatPosture: ThreatPosture = 'Green';
    if (recentLogs.length > 20) threatPosture = 'Red';
    else if (recentLogs.length > 10) threatPosture = 'Yellow';

    const idCounts: Record<string, { val: string, type: string, count: number }> = {};
    currentLogs.forEach(log => {
      const allIds = [
        ...(log.extractedInfo?.upiIds || []).map(i => ({ v: i.value, t: 'UPI' })),
        ...(log.extractedInfo?.phoneNumbers || []).map(i => ({ v: i.value, t: 'TEL' })),
        ...(log.extractedInfo?.links || []).map(i => ({ v: i.value, t: 'URL' }))
      ];
      allIds.forEach(id => {
        if (!id?.v) return;
        const key = id.v.toLowerCase();
        if (!idCounts[key]) idCounts[key] = { val: id.v, type: id.t, count: 0 };
        idCounts[key].count++;
      });
    });

    const topIdentifiers = Object.values(idCounts)
      .sort((a, b) => b.count - a.count)
      .slice(0, 10)
      .map(item => ({ value: item.val, type: item.type, count: item.count }));

    const library: ScamSignature[] = currentLogs
      .filter(l => l.isScam)
      .map(l => ({
        id: l.id,
        type: l.scamType,
        firstMessage: l.originalMessage,
        extractedIndicators: [
            ...(l.extractedInfo?.upiIds || []).map(u => u.value),
            ...(l.extractedInfo?.phoneNumbers || []).map(p => p.value)
        ],
        tactics: l.forensicReport?.psychologicalTactics || ["Social Engineering"],
        timestamp: l.timestamp,
        patternMeta: {
          pattern: l.originalMessage?.length > 60 ? l.originalMessage.substring(0, 60) + '...' : (l.originalMessage || 'N/A'),
          bank: l.sourceIntelligence?.institutionInference || "Multiple",
          method: l.channel?.toUpperCase() || 'UNKNOWN',
          link: (l.extractedInfo?.links && l.extractedInfo.links[0]?.value) || "N/A"
        }
      }));

    const honeypotTotal = currentLogs.filter(l => (l.messages || []).length > 2).length;
    const honeypotSuccess = currentLogs.filter(l => (l.extractedInfo?.upiIds || []).length > 0).length;

    return {
      totalPreventionInr: totalPrevention,
      potentialExposureInr: totalPrevention * 1.5,
      threatPosture,
      topIdentifiers,
      scamLibrary: library,
      honeypotSuccessRate: honeypotTotal ? (honeypotSuccess / honeypotTotal) * 100 : 0,
      governanceMetrics: {
        avgPrivacyScore: 98,
        complianceRate: 100
      }
    };
  }, [currentLogs]);

  const postureColor = {
    'Green': 'text-green-600 bg-green-50 border-green-100',
    'Yellow': 'text-amber-600 bg-amber-50 border-amber-100',
    'Red': 'text-red-600 bg-red-50 border-red-200 animate-pulse'
  }[analytics.threatPosture];

  return (
    <div className="space-y-8 animate-in fade-in duration-700">
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <div className={`p-8 rounded-[2rem] border shadow-2xl flex flex-col justify-center transition-all ${postureColor}`}>
           <div className="text-[10px] font-black uppercase tracking-widest mb-2 opacity-60">{scope === 'Global' ? 'Universal Shield Active' : 'Sovereign Defense Nodes'}</div>
           <div className="text-4xl font-black tracking-tighter uppercase">{analytics.threatPosture} ALERT</div>
           <div className="mt-2 text-[9px] font-bold text-slate-500 uppercase tracking-widest font-mono">Scope: {scope} Grid</div>
        </div>
        <KPIBox title="Shielded Assets" value={`₹${(analytics.totalPreventionInr / 100000).toFixed(2)}L`} sub="Interception Value" color="text-blue-600" />
        <KPIBox title="Memory Store" value={analytics.scamLibrary?.length || 0} sub="Global Scam Patterns" color="text-indigo-600" />
        <KPIBox title="Extraction Quality" value={`${analytics.honeypotSuccessRate.toFixed(1)}%`} sub="IoC Siphoning Rate" color="text-emerald-600" />
      </div>

      <div className="flex space-x-2 bg-slate-100 p-1.5 rounded-2xl w-fit border border-slate-200">
        <TabNav active={activeTab === 'overview'} onClick={() => setActiveTab('overview')} label="Tactical Grid" />
        <TabNav active={activeTab === 'library'} onClick={() => setActiveTab('library')} label="Memory Store (JSON)" />
        <TabNav active={activeTab === 'global'} onClick={() => setActiveTab('global')} label="Global Sync" />
      </div>

      {activeTab === 'overview' && (
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
           <div className="lg:col-span-8 space-y-8">
              <div className="bg-white rounded-[2.5rem] border border-slate-200 p-10 shadow-2xl space-y-6">
                 <h3 className="text-sm font-black text-slate-800 uppercase tracking-widest flex items-center">
                    <span className="w-2 h-2 bg-blue-600 rounded-full mr-2 animate-pulse" />
                    Top Fraud Identifiers (Universal)
                 </h3>
                 <div className="space-y-3">
                    {(analytics.topIdentifiers || []).map((id, i) => (
                      <div key={i} className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl border border-slate-100">
                        <div className="flex flex-col">
                          <span className="text-[10px] font-black text-blue-600 uppercase mb-1">{id.type}</span>
                          <span className="text-xs font-bold font-mono text-slate-800">{id.value}</span>
                        </div>
                        <div className="text-right">
                          <div className="text-[10px] font-black text-slate-400 uppercase">Hits</div>
                          <div className="text-sm font-black text-slate-800">{id.count}</div>
                        </div>
                      </div>
                    ))}
                    {(!analytics.topIdentifiers || analytics.topIdentifiers.length === 0) && (
                      <div className="py-20 text-center text-slate-400 text-[10px] font-bold uppercase tracking-widest italic">No identifiers captured yet.</div>
                    )}
                 </div>
              </div>
           </div>

           <div className="lg:col-span-4 space-y-6">
              <div className="bg-slate-900 rounded-[2rem] p-8 text-white space-y-6">
                 <h4 className="text-[10px] font-black text-blue-500 uppercase tracking-widest">Global Intercept Stream</h4>
                 <div className="space-y-4">
                    {(globalStream || []).map((msg, i) => (
                      <div key={i} className="text-[10px] font-mono text-slate-300 leading-relaxed border-l-2 border-blue-600 pl-3 py-1">
                        {msg}
                      </div>
                    ))}
                 </div>
              </div>
           </div>
        </div>
      )}

      {activeTab === 'library' && (
        <div className="bg-black rounded-[2.5rem] p-10 border border-slate-800 shadow-2xl overflow-hidden">
          <pre className="text-blue-400 font-mono text-xs overflow-x-auto p-4 custom-scrollbar">
            {JSON.stringify(analytics.scamLibrary, null, 2)}
          </pre>
        </div>
      )}

      {activeTab === 'global' && (
        <div className="bg-white rounded-[2.5rem] border border-slate-200 p-10 shadow-2xl flex flex-col space-y-8">
